steps.script:
var cfg = GameState.state["meta"].get("game_config", {})
cfg["player2_type"] = "AI"
GameState.state["meta"]["game_config"] = cfg
return str(cfg.get("player2_type", ""))

var oid = str(SecondaryMissionManager._player_state["1"]["active"][0]["mission_data"].get("tempting_target_id", ""))
var vis = MissionManager.objectives_visual_refs.get(oid, null)
if vis == null or vis.tempting_target_label == null:
	return "<no label>"
return "%s|%s" % [vis.tempting_target_label.text, str(vis.tempting_target_label.visible)]

var found = null
var stack = [tree.root.get_node("/root/SecondaryMissionReviewDialog")]
while stack.size() > 0:
	var n = stack.pop_back()
	if n is Button and str(n.name) == "ReplaceButton_0":
		found = n
	for c in n.get_children():
		stack.append(c)
if found == null:
	return "button-not-found"
found.emit_signal("pressed")
return "pressed"

var vis = null
for oid in MissionManager.objectives_visual_refs:
	var v = MissionManager.objectives_visual_refs[oid]
	if v != null and v.tempting_target_label != null and v.tempting_target_label.visible:
		vis = oid
return vis == null

var mc = tree.root.get_node("/root/Main/SecondaryMissionPanel/PanelVBox/MissionScroll/MissionContent")
var hits = 0
for c in mc.get_children():
	if c is Label and (str(c.text).begins_with("YOUR MISSIONS") or str(c.text).begins_with("OPPONENT'S MISSIONS")):
		hits += 1
return hits

var mc = tree.root.get_node("/root/Main/SecondaryMissionPanel/PanelVBox/MissionScroll/MissionContent")
var txt = ""
var stack = []
for c in mc.get_children():
	stack.append(c)
while stack.size() > 0:
	var n = stack.pop_back()
	if n is Label:
		txt += str(n.text) + "\n"
	for c in n.get_children():
		stack.append(c)
return txt.findn("A Tempting Target") != -1
